      + p.set_aside.filter(x => x.dropped).map(x => esc(x.note || (x.keyword + ' — ' + x.detail))).join(' | ') + '</p>' : '') +
    // B8-2 / B8-3: what today was measured on, and which earlier days it could honestly be compared with
    ((readable.note || baseline_note) ? '<p style="font-size:12px;color:#b45309;margin:6px 0">' + (readable.note ? '<b>' + esc(readable.note) + '</b>' : '') + (readable.note && baseline_note ? ' ' : '') + esc(baseline_note) + '</p>' : '') +
    // B8-9: how many tests today's alerts were judged across, and at what threshold
    (multiple_tests.tests ? '<p style="font-size:12px;color:#475569;margin:6px 0">' + esc(multiple_tests.note.replace('of this run', 'of today\'s run')) + '</p>' : '') +
    '<p style="font-size:12px;color:#64748b">The weekly AI visibility report (' + (p.cycle_weekday_known ? ST.everyText(p.cycle_weekday) : 'each week') + ') adds these daily answers to its figures. Answers vary from one ask to the next; an alert is sent only when a change is beyond that noise, measured against earlier days that asked the same questions of the same engines.</p></div>';
  return { json: { site_id: p.site_id, domain: p.domain, date: p.date, email: p.email, callback_url: p.callback_url, request_id: p.request_id, on_demand: p.on_demand, alerts, daily_row, answer_rows, subject, html,
    set_aside: p.set_aside || [], set_aside_note: p.set_aside_note || '',   // B-G2 / B-G1: the refusals travel to the app and the callback too
    samples: n, mention_rate: pct(m, n), mention_ci: [lo, hi], citation_rate: pct(c, n), visibility_score: visibility, engines, errors, error_rate, errors_list: error_list, retried: retry.asked, retry_answered: retry.answered,
    // B8-2 / B8-3: what today could be read, and which earlier days it is honestly comparable with — both travel to the app and the callback
    readable, today_rate: todayRate, baseline_days: B.length, baseline_of: judged.length, baseline_set_aside, baseline_note,
    multiple_tests: { method: multiple_tests.method, alpha: multiple_tests.alpha, tests: multiple_tests.tests, threshold_p: multiple_tests.threshold_p, threshold_z: multiple_tests.threshold_z, rejected: multiple_tests.rejected, results: multiple_tests.results, note: multiple_tests.note },   // B8-9
    sample: p.sample || null, panel_size: p.panel_size || p.prompts.length,   // G6
    // F1b (2026-10-23): the rule today's figures were counted under, and the place in the answers with its sample
    rule_version: AVM.RULE_VERSION, share_of_voice: daily_row.share_of_voice, sov_answers: day.sov_n, avg_position: day.avg_position, position_answers: day.position_n, first_rate: day.first_rate,
    sample_mode: daily_row.sample_mode, questions_asked: daily_row.questions_asked, partial: daily_row.partial,
    status: 'progress', stage: 'ai_pulse', checked_at: p.checked_at } };
});

// Today's answer rows for seo_ai_answers (run_kind pulse; exact columns, short excerpts; kept 35 days).
const rows = $('Pulse Metrics').all().flatMap(i => i.json.answer_rows || []);
return rows.length ? rows.map(r => ({ json: r })) : [{ json: { skip: true } }];

// One seo_ai_daily row per site and reading (exact columns). The weekly AI visibility run adds them to its figures.
// R95 (2026-10-16, re-rating C-19): the upsert key was site + date, so a same-day ON-DEMAND pulse (exec 630, 19:42) replaced that day's SCHEDULED
// reading (exec 593, 11:11) and the week counted the day once, with the later sample. An on-demand reading now gets its own run_id, so it is
// stored beside the scheduled one (upsert by site + date + run_id); a scheduled re-run of the same day still replaces only the scheduled row.
const rows = $('Pulse Metrics').all().map(i => (i.json.daily_row ? { ...i.json.daily_row, run_id: i.json.on_demand ? String(i.json.daily_row.run_id || 'pulse') + '_on_demand_' + $execution.id : i.json.daily_row.run_id } : null)).filter(r => r && r.samples > 0);
return rows.length ? rows.map(r => ({ json: r })) : [{ json: { skip: true } }];

// R-E7: a Data Table update / delete answers with every row it changed; only the count goes on.
const n = $input.all().filter(i => i.json && !i.json.error && i.json.id != null).length;
return [{ json: { changed: n } }];

// Sites with something to report (an alert, or an on-demand run): the e-mail and the callback (stage ai_pulse). Quiet days send nothing.
const out = $('Pulse Metrics').all().map(i => i.json).filter(m => (m.alerts || []).length || m.on_demand).map(m => { const { daily_row, answer_rows, ...rest } = m; return { json: rest }; });
return out.length ? out : [{ json: { skip: true } }];

// F-ENG (2026-10-20): the next part of this morning's pulse (Pulse Plan's `pulse_next`: the websites after the last one this part took),
// started through the workflow's own Manual Run. None when every website was served.
const n = ($('AI Plan').first().json || {}).pulse_next;
return n && n.pulse_part ? [{ json: n }] : [{ json: { skip: true } }];

// D19 / G1 (system review of 2026-10-11, FIX_PLAN.md; the retry-gate pattern of build_v4.py section 25): DataForSEO reports a task error
// *inside* an HTTP 200 (`status_code` 40000-50000, e.g. "Internal SE Server Error."), which n8n's `retryOnFail` never sees. In execution
// 362 / 363 seven of 42 requests failed that way (AI Mode and AI Overview x5, ChatGPT "no response" x2) and the week's figures were quietly
// computed on the rest. Every failed request is now re-sent ONCE, after a pause (*Wait Before AI Retry*), and *Merge AI Answers* puts the
// retry's answer in the failed one's place before *Parse AI Answers* reads them.
// Only the failed requests are re-sent (the bodies are the same items), so the retry can cost at most what the failures cost — a failed
// DataForSEO task is billed 0 — and never more than CONFIG.max_retries of them. Shared by the AI Visibility Tracker and the AI Pulse.
const CONFIG = { max_retries: 24 };
const reqs = $('AI Requests').all().map(i => i.json);
const resps = $input.all().map(i => i.json || {});
if (!reqs.length || reqs[0].skip) return [{ json: { skip: true, reason: 'nothing was asked' } }];
const out = []; let failed = 0;
reqs.forEach((q, i) => {
  const r = resps[i] || {}; const task = (r.tasks || [])[0] || {}; const res = (task.result || [])[0];
  const code = Number(task.status_code) || 0;
  let why = '';
  if (r.error) why = 'request failed: ' + String((r.error && (r.error.message || r.error)) || 'error').slice(0, 120);
  else if (!code) why = 'no response';
  else if (code >= 40000) why = 'task error ' + code + ': ' + String(task.status_message || '').slice(0, 100);
  else if (code === 20000 && !res) why = 'no answer in the task';   // an AI Overview that is simply not shown IS an answer: the task carries a result
  if (!why) return;
  failed++;
  if (out.length >= CONFIG.max_retries) return;
  out.push({ json: { ...q, retry_of: i, retry_reason: why, is_retry: true } });
});
if (!out.length) return [{ json: { skip: true, reason: failed ? 'nothing to retry' : 'every request answered', failed } }];
out[0].json.retry_total = out.length; out[0].json.failed_total = failed;
return out;

// D19 (system review of 2026-10-11, FIX_PLAN.md): the answers of *Run AI Requests* with every retried request's answer put back in its own
// place, so the item order still matches *AI Requests* one to one (*Parse AI Answers* and *AI Metrics* pair them by index). A retry replaces
// the first answer only when it really came back (task status 20000 with a result); otherwise the original failure is kept, with its message,
// and the run reports the failure instead of hiding it. The first item carries the counts for the report ("3 of 42 requests failed, 2 answered
// on the retry"). Shared by the AI Visibility Tracker and the AI Pulse.
const base = $('Run AI Requests').all().map(i => i.json || {});
let rq = [], rr = [];
try { rq = $('AI Retry Requests').all().map(i => i.json || {}).filter(q => !q.skip); } catch (e) {}
try { rr = $('Run AI Retries').all().map(i => i.json || {}); } catch (e) {}
const ok = (r) => { const t = ((r || {}).tasks || [])[0] || {}; return !(r || {}).error && Number(t.status_code) === 20000 && !!(t.result || [])[0]; };
const out = base.map(x => ({ ...x }));
let fixed = 0;
rq.forEach((q, k) => {
  const i = Number(q.retry_of); const r = rr[k];
  if (!(i >= 0) || i >= out.length || !r) return;
  if (!ok(r)) return;
  out[i] = { ...r, retried: true, retry_reason: q.retry_reason || '' };
  fixed++;
});
if (out.length) { out[0].retry_asked = rq.length; out[0].retry_answered = fixed; out[0].requests_failed = Number((rq[0] || {}).failed_total) || rq.length; }
return out.length ? out.map(j => ({ json: j })) : [{ json: {} }];

// R9 (2026-10-13, re-rating RESULTS §3.2): the daily spend guard saw only the main workflow and the Keyword Check. seo_run_ledger had no row at
// all for the AI Pulse, the Rank Tracker, the Content Cadence, the Link Builder, AI Growth or the Site Tracker (execs 502, 505, 506, 508, 511,
// 515), although the pulse alone cost $0.084 and the monitors accounted for about $0.18 of that run's $0.578 of DataForSEO — so two
// customer-facing runs were refused for AI estimates while the measured money went out unguarded.
// This is the same reservation the main workflow makes (one appended row per execution, settled at the end), hung BESIDE the plan node: a Data
// Table node answers with the row it wrote, not with its input, so the ledger must never sit in the monitor's own data path. The row is for the
// record and for the main workflow's guard, which now sees what the schedules spend; a monitor is never refused by it.
// MODE / EST / HEAVY are written in by the builder at build time (one source: build_monitors.py's WF.run_ledger).
const PLAN = 'AI Plan';
const MODE = 'ai_pulse';
const EST = {"ai": 0.004, "dfs": 0.08};   // { ai: <usd per site>, dfs: <usd per site>, dfs_full?: <usd per site for a full run> }
const n0 = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
let rows = [];
try { rows = $(PLAN).all().map(i => i.json || {}).filter(r => !r.nothing_to_do && !r.skip && (r.domain || r.site_id)); } catch (e) { rows = []; }
const full = (r) => EST.dfs_full != null && (String(r.mode || '') === 'full' || r.full === true || r.full_report === true);
// R31 (2026-10-14, FIX_PLAN §3.13): a `free_only` run calls no paid API and no model at all — it uses the free sources and our own link
// check ($0, and the callback tells the caller `cost_usd: 0`). It used to reserve the full per-site figure anyway ($0.05 Claude + $0.45
// DataForSEO on exec 586) and then settle the Claude half, so the guard held back money the run could not spend and the ledger said it
// had. A free run reserves nothing.
const free = (r) => r.free_only === true || r.free === true || String(r.mode || '') === 'free';
const paid = rows.filter(r => !free(r));
const freeRows = rows.length - paid.length;
// G6 (2026-10-18): a plan that prices its own sites (the AI Visibility Tracker and the AI Pulse: the exact estimate of THIS panel — up to 500
// questions on up to 9 engines — minus what earlier executions of a split run already spent) is reserved at that figure, not at a flat per-site
// one; the run guard's balance floor then refuses a run the account cannot pay for. Every other plan keeps the per-site figure.
const own = (r, k) => r[k] !== undefined && r[k] !== null && r[k] !== '' && Number.isFinite(Number(r[k]));
const priced = paid.filter(r => own(r, 'est_dfs_usd') || own(r, 'est_ai_usd')).length;
const ai = +paid.reduce((s, r) => s + (own(r, 'est_ai_usd') ? n0(r.est_ai_usd) : n0(EST.ai)), 0).toFixed(4);
const dfs = +paid.reduce((s, r) => s + (own(r, 'est_dfs_usd') ? n0(r.est_dfs_usd) : (full(r) ? n0(EST.dfs_full) : n0(EST.dfs))), 0).toFixed(4);
// one site in the run: name it, as the main workflow's reservation does (P34-5 reads `domain` to refuse a second heavy crawl of the same site).
// 2026-10-19: one site even when the plan emits one item per CHECK (the Rank Tracker of one website: every item carries the same domain), and
// a cycle / on-demand run names its site from the trigger when its plan had nothing to do - the run guard's twin rule is per site now
// (RG.gate `site`) and the Cycle Dispatcher reads the row of a job that ran nothing like any other.
const __doms = [...new Set(rows.map(r => String(r.domain || '').toLowerCase().trim()).filter(Boolean))];
let __trig0 = {};
for (const __n of ['Manual Run', 'Watch Run']) { try { const __t = $(__n).first(); if (__t && __t.json) { __trig0 = __t.json; break; } } catch (e) {} }
if (__trig0.body && typeof __trig0.body === 'object') __trig0 = { ...__trig0, ...__trig0.body };
const __trigDom = String(__trig0.domain || '').toLowerCase().trim().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/[\/?#].*$/, '');
const domain = __doms.length === 1 ? __doms[0] : (!__doms.length ? __trigDom : '');
// R32: the account balance at the moment this row is reserved, from the free appendix/user_data probe on the ledger chain.
let dfs_balance = 0;
try { const __b = $('DFS Balance (Pulse)').first().json || {}; const __t = (__b.tasks || [])[0] || {}; const __r = (__t.result || [])[0] || {};
  const __v = Number((__r.money || {}).balance); if (Number.isFinite(__v) && __v > 0) dfs_balance = +__v.toFixed(6); } catch (e) {}
// R77 (2026-10-16, re-rating C-1): an on-demand run started by the main workflow's front door carries that run's execution id as
// `parent_run_id` on its trigger item (Monitor Start). The row names it in its key — `parent:<id>` instead of `schedule:<mode>` — so the gate
// (RG.parentOf) does not count the parent's own reserved row as a twin, and the two rows of one request are linked in the table (R81: the
// parent settles $0 as handed off; the money is on this row). A scheduled run has no trigger item and keeps `schedule:<mode>`.
let __trig = {};
for (const __n of ['Manual Run', 'Watch Run']) { try { const __t = $(__n).first(); if (__t && __t.json) { __trig = __t.json; break; } } catch (e) {} }
if (__trig.body && typeof __trig.body === 'object') __trig = { ...__trig, ...__trig.body };
const parent_run_id = String(__trig.parent_run_id == null ? '' : __trig.parent_run_id).trim();
// 2026-10-19 (SCHEDULING_KEYWORDS_PLAN.md §4.5 / §14.2 / §15): a run of a website's weekly cycle is keyed `cycle:<cycle_key>:<job>` - the
// Cycle Dispatcher reads exactly that row to know the job is done (settled), refused for capacity (retried without spending an attempt) or
// failed. It is autopilot spend, like `schedule:`. A job that runs in several executions (the AI Visibility Tracker's split run) settles that
// key only in its FINAL execution; every earlier part is `cycle:<cycle_key>:<job>:part<n>`, so a part that finished is never read as the job
// finished. The parent of a continuation is still known to the run guard by the trigger's `parent_run_id`.
const JOB_OF = { ai_visibility: 'ai_visibility', backlinks: 'backlinks', rank_tracker: 'rank_tracker', site_tracker: 'site_tracker', ai_growth: 'ai_growth',
  content_cadence: 'content_cadence', link_builder: 'link_builder', audit_schedule: 'audit', ai_pulse: 'ai_pulse', page_watch: 'page_watch' };
const __cycKey = String(__trig.trigger || '') === 'cycle' ? String(__trig.cycle_key || '').trim() : '';
const __job = String(__trig.job || '').trim() || JOB_OF[MODE] || MODE;
const __part = (() => { const c = (rows[0] || {}).chunk; return c && typeof c === 'object' && c.final_expected === false ? Math.max(1, Number(c.no) || 1) : 0; })();
const __key = __cycKey ? 'cycle:' + __cycKey + ':' + __job + (__part ? ':part' + __part : '') : (parent_run_id ? 'parent:' + parent_run_id : 'schedule:' + MODE);
return [{ json: { run_id: String($execution.id), key: __key, mode: MODE, est_usd: ai, created_at: new Date().toISOString(),
  status: 'reserved', settled_usd: 0, domain, heavy: false, dfs_est_usd: dfs, dfs_usd: 0,
  // R28 (2026-10-14): the DataForSEO balance at reservation time, read for free from appendix/user_data so the day's reported spend can be
  // held against the account. R32 (2026-10-14, FIX_PLAN §3.13): a scheduled run takes the reading too — until now only main-workflow runs
  // did, so a Monday of monitor spend reconciled against nothing at all. One free call per run (not per site); 0 = the probe did not answer.
  dfs_balance,
  // G23 (2026-10-13): a row must say which part of its money was measured and which estimated; at reservation time none of it is measured.
  // `cost_mode` is the key of the self-correcting rolling figure in seo_cache (`cost:<kind>:<mode>`) this run will settle into.
  cost_mode: MODE, ai_usd: 0, measured_usd: 0, estimated_usd: +(ai + dfs).toFixed(4),
  // R31 (2026-10-14): $0 is never called an estimate - a run that reserves nothing says so, with the reason.
  cost_basis: ((ai + dfs) > 0
    ? (priced ? 'reserved: Claude $' + ai.toFixed(4) + ' ESTIMATED (' + priced + ' site(s) priced from their own panel and engines' + (paid.length > priced ? ', ' + (paid.length - priced) + ' at the per-site figure' : '') + '), DataForSEO $' + dfs.toFixed(4) + ' ESTIMATED - nothing measured yet'
      : 'reserved: Claude $' + ai.toFixed(4) + ' ESTIMATED (' + paid.length + ' site(s) x the per-site figure), DataForSEO $' + dfs.toFixed(4) + ' ESTIMATED - nothing measured yet')
    : 'reserved: nothing - this run spends no model and no paid API money'
    ) + (freeRows ? '; ' + freeRows + ' free-only site(s) reserve nothing (no paid API, no model call)' : ''),
  // B-A5 (2026-10-15, build section 62): filled in by the settle — when it settled, what the account read then, and whether the figure
  // the row carries is the account's ('account') or the run's own tasks' ('tasks').
  settled_at: '', dfs_balance_end: 0, dfs_source: 'tasks' } }];

// ---- CK: is a model's answer complete? (LLM-LIMITS, 2026-10-27, docs/llm-limits-2026-10-27/LIMITS.md) ----
// Production (techand.ai, execution 2195): the Editor's answer stopped mid-word ("Does the add-on cover gratu") when the model reached
// its max_tokens ceiling; n8n hands a stream cut that way on as a success (the stop reason is dropped, the agent outputs only `output`),
// so the run replaced a complete 1,804-word page with 749 words and delivered half a page. Nothing in the answer says it was cut, so this
// kit reads the answer itself, deterministically:
//   CK.text(md)            a long text (page, brief, e-mail, report) ends cleanly: not mid-word / mid-sentence, markdown balanced,
//                          no unfinished list item, table row or code block, no heading left without its text.
//   CK.edit(before, after) an edit of a complete text is itself complete AND did not lose the end: under 75% of the input's main-text
//                          words (40% when the edit was asked to cut) or two of its sections gone is a cut, not an edit.
//   CK.json(raw)           a JSON answer parses completely; an answer that stops inside its JSON is `truncated`, never an empty answer.
//   CK.answer(item, kind)  one agent item (n8n `{ output }`, or `{ error }` after its retry) -> { complete, truncated, reason }.
// Pure: no clock, no network, no n8n globals, so the harness replays it. Every `reason` is plain words a customer can read.
const CK = (() => {
  const words = (s) => String(s || '').split(/\s+/).filter(Boolean).length;
  const META = /^(Title|Meta Description|Meta Title|Slug|Primary Keyword|Secondary Keywords|URL|Page Type)\s*:/i;
  const LIST = /^\s*(?:[-*+]|\d{1,3}[.)])\s+/;
  const QUESTION_START = /^(?:\*\*[^*]{1,80}\*\*\s*:?\s*)?(?:does|do|did|is|are|was|were|can|could|will|would|should|shall|what|which|how|who|whom|whose|why|when|where|have|has)\b/i;
  const DANGLING = /\b(?:and|or|but|nor|the|a|an|of|to|for|with|in|on|at|by|from|that|which|who|is|are|was|were|be|as|than|then|if|so|such|into|onto|about|your|our|their|its|this|these|those|e\.g|i\.e)$/i;
  const SIGN_OFF = /^(?:best|kind|warm|many thanks|thanks|thank you|regards|cheers|sincerely|all the best|best wishes|with thanks)\b[^.!?]{0,30}[,.!]?$/i;
  const END_PUNCT = /[.!?]["'”’)\]*_]*$/;
  // a link, an address, or a bracketed call to action / field at the very end ("[Book my free call] · [Message us on WhatsApp]",
  // "[Credentials and years of experience]"): a cut answer almost never stops exactly on a closing bracket, so these end cleanly
  const LINK_END = /\]\([^()\s]*\)[*_]*[.!?]?$|<https?:\/\/[^>\s]+>$|^https?:\/\/\S+$|\][*_]*$/;
  const isTableRow = (l) => /^\s*\|/.test(l);
  const cells = (l) => String(l).trim().replace(/^\|/, '').replace(/\|$/, '').split('|').length;
  const unbalanced = (t) => {
    const s = String(t || '').replace(/`[^`]*`/g, '');
    const bold = (s.match(/\*\*/g) || []).length;
    if (bold % 2) return 'a bold phrase is not closed';
    const open = (s.match(/\[/g) || []).length, close = (s.match(/\]/g) || []).length;
    if (open > close) return 'a link or bracket is not closed';
    const lp = (s.match(/\]\(/g) || []).length, lpc = (s.match(/\]\([^()\s]*\)/g) || []).length;
    if (lp > lpc) return 'a link address is not closed';
    return '';
  };

  // the body without the meta lines the writers put at the top, trailing blanks dropped
  const bodyLines = (md) => {
    const lines = String(md == null ? '' : md).replace(/\r/g, '').split('\n');
    let i = 0; while (i < lines.length && (META.test(lines[i].trim()) || !lines[i].trim())) i++;
    const out = lines.slice(i); while (out.length && !out[out.length - 1].trim()) out.pop();
    return out;
  };

  // "Best regards," / "Thanks," then one or two short lines (the name, a title or company line): an e-mail that ends cleanly
  const signedOff = (lines) => { for (const k of [2, 3]) { if (lines.length < k) continue; const head = lines[lines.length - k].trim();
    if (!(SIGN_OFF.test(head) || (/,$/.test(head) && words(head) <= 4))) continue;
    if (lines.slice(lines.length - k + 1).every(l => l.trim() && words(l) <= 7 && !/[.!?]$/.test(l.trim()) && !LIST.test(l))) return true; }
    return false; };
  // the contiguous list block that ends at index `end`
  const listBlock = (lines, end) => { const out = []; for (let i = end; i >= 0 && LIST.test(lines[i]); i--) out.unshift(lines[i]); return out; };

  const text = (md, opts) => {
    const o = opts || {};
    const minWords = o.min_words == null ? 0 : Number(o.min_words);
    const lines = bodyLines(md);
    const reasons = [];
    const body = lines.join('\n');
    const n = words(body);
    if (!n) return { complete: false, cut_off: true, empty: true, words: 0, last_line: '', reasons: ['the answer is empty'] };
    if (minWords && n < minWords) reasons.push('the answer has ' + n + ' words, far below the ' + minWords + ' expected');
    const fences = lines.filter(l => /^\s*(```|~~~)/.test(l)).length;
    if (fences % 2) reasons.push('a code block is not closed');
    const last = lines[lines.length - 1].trim();
    const lastPlain = last.replace(/[*_`]+$/g, '').trim();
    if (/^#{1,6}\s/.test(last)) reasons.push('the last heading has no text under it');
    else if (isTableRow(last)) {
      let h = lines.length - 1; while (h > 0 && isTableRow(lines[h - 1])) h--;
      const want = cells(lines[h]);
      if (!/\|\s*$/.test(last)) reasons.push('the last table row is cut off');
      else if (cells(last) < want) reasons.push('the last table row has ' + cells(last) + ' of its ' + want + ' cells');
    } else if (/^\s*(```|~~~)\s*$/.test(last)) {
      // a closed code block: complete as far as this line goes
    } else if (/^!\[[^\]]*\]\([^()\s]+\)$/.test(last) || /^\[[^\]]+\]\([^()\s]+\)$/.test(lastPlain.replace(/^[*_]+/, ''))) {
      // an image or a link on its own line (a call to action): complete
    } else if (LIST.test(last)) {
      const item = last.replace(LIST, '').trim();
      const itemPlain = item.replace(/[*_`]+$/g, '').trim();
