      next_attempt_at: res.ok || giveUp ? '' : iso(nowMs + RETRY_MINUTES * 60000),
      attempt_log: addAttempt(r, attempt, iso(nowMs), 'webhook', res.ok, res.detail),
      notes: (res.ok
